    {(menu?.object || menu?.classMeta || menu?.file) && <div ref={popupRef} className="popup" style={{ left: menu.x, top: popupTop ?? menu.y }} onClick={event => event.stopPropagation()}><div className="popup-title">{menu.object?.className || menu.classMeta?.name || fileClassName(menu.file!)}</div>{(generation ? (menu.object ? [] : menu.classMeta?.kind === 'class' ? classPopupItems(menu.classMeta) : menu.classMeta?.methods) : [])?.map((meta, index, all) => <React.Fragment key={meta.id}>{meta.inheritedFrom && meta.inheritedFrom !== all[index - 1]?.inheritedFrom && <div className="popup-group">inherited from {meta.inheritedFrom}</div>}<button className={(meta as any).isConstructor ? 'constructor-menu-item' : undefined} disabled={executing} onClick={() => { if ((meta as any).isConstructor) { openCreate(menu.classMeta!, (meta as any).index); setMenu(null); return; } const visibleMeta = menu.object ? specializeCallable(meta, menu.object, classes) : meta; const receiver = menu.object ? '' : (menu.classMeta?.kind === 'object' || (meta as any).isCompanion) ? `${menu.classMeta.name}.` : ''; if (!(visibleMeta.parameters || []).length && !(visibleMeta.typeParameters || []).length) { const request = menu.object ? accessorRequest(menu.object, visibleMeta, []) || { op: 'invoke', objectId: menu.object.objectId, name: visibleMeta.name, args: '[]' } : !menu.object && menu.classMeta?.kind === 'functions' && visibleMeta.name === 'main' ? { op: 'main', fileName: `${menu.classMeta.name}.kt` } : { op: 'eval', code: `${receiver}${visibleMeta.name}()`, mode: 'expression' }; action(request).then(showReturnedObject); setMenu(null); } else { setMethod({ object: menu.object, receiver, meta: visibleMeta }); setMethodArgs(visibleMeta.parameters.map(() => '')); setMethodTypeArgs((visibleMeta.typeParameters || []).map(() => '')); setMenu(null); } }}>{(meta as any).isConstructor ? `${menu.classMeta!.name}(${signatureParams(meta.parameters)})` : methodText(menu.object ? specializeCallable(meta, menu.object, classes) : meta)}</button></React.Fragment>)}{generation && menu?.object && <>{inheritedPopupGroups.map(([owner, methods], index) => <React.Fragment key={owner}><div className="popup-submenu"><button className="popup-submenu-trigger" onClick={event => event.stopPropagation()}>inherited from {owner}<span>›</span></button><div className="popup-submenu-panel">{methods.map(popupMethodButton)}</div></div>{index === inheritedPopupGroups.length - 1 && <hr />}</React.Fragment>)}{directPopupMethods.length ? directPopupMethods.map(popupMethodButton) : <div className="popup-no-methods">(No accessible methods)</div>}</>}{menu.file && <><hr /><button onClick={() => openFile(menu.file!)}>Open Editor</button><button disabled={compiling || executing} onClick={() => { setMenu(null); compile(); }}>Compile</button><button disabled={compiling || executing} onClick={() => deleteFile(menu.file!)}>Delete</button><button disabled={compiling || executing} onClick={() => duplicateFile(menu.file!)}>Duplicate…</button></>}{menu.object && <><hr /><button disabled={executing} onClick={() => { inspectBenchObject(menu.object!); setMenu(null); }}>Inspect</button><button disabled={executing} onClick={() => { const removedId = menu.object!.objectId; if (!menu.object!.synthetic) action({ op: 'remove', objectId: removedId }); setBench(previous => previous.filter(object => object.objectId !== removedId)); if (selectedObjectId === removedId) setSelectedObjectId(''); setMenu(null); }}>Remove</button></>}</div>}
