    {newProjectDialog && <div className="modal" onClick={() => setNewProjectDialog(false)}><div className="dialog new-project-dialog" onClick={event => event.stopPropagation()}><h3>Create New Project</h3><p>Choose a starting point:</p><div className="project-choice-list"><button onClick={() => createProject('empty')}><strong>Empty Project</strong><span>Start with no Kotlin files.</span></button><button onClick={() => createProject('kotlin-example')}><strong>Kotlin Example</strong><span>A small example with classes, inheritance, and common Kotlin features.</span></button><div className="project-choice-with-info"><button onClick={() => createProject('blueplay-empty')}><strong>BluePlay Template</strong><span>An empty BluePlay template.</span></button><button className="project-info-button" aria-label="What is BluePlay?" onClick={() => setProjectInfo('blueplay-template')}>?</button></div><div className="project-choice-with-info"><button onClick={() => createProject('blueplay-example')}><strong>BluePlay – Example</strong><span>A small World and Actor subclass example.</span></button><button className="project-info-button" aria-label="What is BluePlay?" onClick={() => setProjectInfo('blueplay-example')}>?</button></div></div><div className="dialog-actions"><button onClick={() => setNewProjectDialog(false)}>Cancel</button></div>{projectInfo && <div className="project-info-panel" role="dialog" aria-modal="true" aria-labelledby="blueplay-info-title"><button className="project-info-close" aria-label="Close BluePlay information" onClick={() => setProjectInfo(null)}>×</button><h4 id="blueplay-info-title">What is BluePlay?</h4><p>BluePlay is a very small framework for creating graphical games and simulations with Kotlin.</p><p>It provides simple building blocks such as worlds, actors, and images, so beginners can focus on object-oriented programming.</p><p>The framework is intentionally lightweight and easy to explore instead of trying to be a full game engine.</p><p>Both the template and the example project show how these building blocks can be used.</p><p><a href="https://github.com/tomkarp/BluePlay" target="_blank" rel="noreferrer">View the BluePlay project on GitHub</a></p></div>}</div></div>}
